int main() {
    const int N = 5;
    vector<vector<int>> grid(N, vector<int>(N));

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> grid[i][j];
        }
    }

    // Convert grid to histogram heights
    vector<vector<int>> heights(N, vector<int>(N, 0));
    for (int j = 0; j < N; ++j) {
        heights[0][j] = grid[0][j];
    }
    for (int i = 1; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] == 1) {
                heights[i][j] = heights[i-1][j] + 1;
            } else {
                heights[i][j] = 0;
            }
        }
    }

    int maxArea = 0;

    // For each row, find largest rectangle in histogram
    for (int i = 0; i < N; ++i) {
        for (int left = 0; left < N; ++left) {
            int minHeight = heights[i][left];
            for (int right = left; right < N; ++right) {
                minHeight = min(minHeight, heights[i][right]);
                if (minHeight == 0) break;
                int area = minHeight * (right - left + 1);
                maxArea = max(maxArea, area);
            }
        }
    }

    cout << maxArea << endl;

    return 0;
}

