int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> grid;
    string s;

    while ((int)grid.size() < 5 && cin >> s) {
        string t;
        for (char c : s) {
            if (c == '0' || c == '1') t += c;
        }
        if ((int)t.size() == 5) {
            grid.push_back(t);
        } else {
            // If input has spaces between digits, keep reading until 5 digits collected
            while ((int)t.size() < 5 && cin >> s) {
                for (char c : s) {
                    if (c == '0' || c == '1') t += c;
                }
            }
            if ((int)t.size() >= 5) {
                t = t.substr(0, 5);
                grid.push_back(t);
            }
        }
    }

    int best = 0;

    for (int r1 = 0; r1 < 5; ++r1) {
        for (int r2 = r1; r2 < 5; ++r2) {
            for (int c1 = 0; c1 < 5; ++c1) {
                for (int c2 = c1; c2 < 5; ++c2) {
                    bool ok = true;
                    for (int i = r1; i <= r2 && ok; ++i) {
                        for (int j = c1; j <= c2; ++j) {
                            if (grid[i][j] != '1') {
                                ok = false;
                                break;
                            }
                        }
                    }
                    if (ok) {
                        int area = (r2 - r1 + 1) * (c2 - c1 + 1);
                        best = max(best, area);
                    }
                }
            }
        }
    }

    cout << best << '\n';
    return 0;
}

#include <stdio.h>

int largestRectangleInHistogram(int *heights, int n) {
    int stack[10], top = -1;
    int maxArea = 0;
    int i;
    for (i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > h) {
            int height = heights[stack[top--]];
            int width = (top < 0) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) maxArea = area;
        }
        stack[++top] = i;
    }
    return maxArea;
}

