def largest_rectangle(grid):
    rows = 5
    cols = 5
    max_area = 0

    # Height of histogram for each column
    heights = [0] * cols

    for i in range(rows):
        # Update heights
        for j in range(cols):
            if grid[i][j] == '1':
                heights[j] += 1
            else:
                heights[j] = 0

        # Calculate max rectangle in histogram
        stack = []
        for j in range(cols + 1):
            current_height = heights[j] if j < cols else 0
            while stack and current_height < heights[stack[-1]]:
                h = heights[stack.pop()]
                width = j if not stack else j - stack[-1] - 1
                area = h * width
                if area > max_area:
                    max_area = area
            stack.append(j)

    return max_area


